<?php
declare(strict_types=1);

function process_mapping_tables():array{return['business_processes','business_process_versions','business_process_lanes','business_process_steps','business_process_transitions','business_process_controls','business_process_integrations','business_process_assignments','business_process_instances','business_process_step_instances','business_process_exceptions','business_process_events'];}
function process_mapping_tables_ready():bool{if(data_is_demo())return true;$pdo=production_database_connection();if(!$pdo)return false;try{$n=process_mapping_tables();$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('.implode(',',array_fill(0,count($n),'?')).')');$s->execute($n);return(int)$s->fetchColumn()===count($n);}catch(Throwable){return false;}}
function process_mapping_require_tables():void{if(!process_mapping_tables_ready())throw new RuntimeException('Import the Section 25 migration before using Production Data process-mapping writes.');}
function process_mapping_demo_collection(string$key,callable$seed):array{if(!isset($_SESSION['gruber_demo_state'][$key]))$_SESSION['gruber_demo_state'][$key]=$seed();return array_values($_SESSION['gruber_demo_state'][$key]);}
function process_mapping_demo_save(string$key,array$r,callable$seed):array{$rows=process_mapping_demo_collection($key,$seed);$id=(int)($r['id']??0);if($id<=0){$id=max([0,...array_map('intval',array_column($rows,'id'))])+1;$r['id']=$id;$rows[]=$r;}else{$found=false;foreach($rows as$i=>$row)if((int)$row['id']===$id){$rows[$i]=array_replace($row,$r);$r=$rows[$i];$found=true;break;}if(!$found)$rows[]=$r;}$_SESSION['gruber_demo_state'][$key]=array_values($rows);return$r;}
function process_mapping_raw_rows(string$table,string$key,callable$seed,string$order='id'):array{if(data_is_demo())return process_mapping_demo_collection($key,$seed);if(!process_mapping_tables_ready())return[];return production_database_connection()->query("SELECT * FROM {$table} ORDER BY {$order}")->fetchAll();}
function process_mapping_visible_entity_ids():array{return entity_system_visible_entity_ids();}
function process_mapping_visible_process_ids():array
{
    $processes=process_mapping_raw_rows('business_processes','business_processes','process_mapping_demo_processes','process_name,id');
    if(can_use_enterprise_view())return array_map('intval',array_column($processes,'id'));
    $entities=array_fill_keys(process_mapping_visible_entity_ids(),true);$visible=[];$today=date('Y-m-d');
    foreach(process_mapping_raw_rows('business_process_assignments','business_process_assignments','process_mapping_demo_assignments','process_id,entity_id')as$a){if(!isset($entities[(int)$a['entity_id']])||($a['status']??'active')!=='active')continue;if(!empty($a['effective_from'])&&(string)$a['effective_from']>$today)continue;if(!empty($a['effective_to'])&&(string)$a['effective_to']<$today)continue;$visible[(int)$a['process_id']]=true;}
    foreach(process_mapping_raw_rows('business_process_instances','business_process_instances','process_mapping_demo_instances','created_at DESC,id DESC')as$i)if(isset($entities[(int)$i['entity_id']]))$visible[(int)$i['process_id']]=true;
    return array_map('intval',array_keys($visible));
}
function process_mapping_processes():array{$visible=array_fill_keys(process_mapping_visible_process_ids(),true);return array_values(array_filter(process_mapping_raw_rows('business_processes','business_processes','process_mapping_demo_processes','process_name,id'),static fn(array$r):bool=>isset($visible[(int)$r['id']])));}
function process_mapping_versions(?int$processId=null):array{$processes=array_fill_keys(process_mapping_visible_process_ids(),true);$r=array_values(array_filter(process_mapping_raw_rows('business_process_versions','business_process_versions','process_mapping_demo_versions','process_id,id DESC'),static fn(array$x):bool=>isset($processes[(int)$x['process_id']])));return$processId===null?$r:array_values(array_filter($r,fn($x)=>(int)$x['process_id']===$processId));}
