function process_mapping_events():array{$processes=array_fill_keys(process_mapping_visible_process_ids(),true);$instances=array_fill_keys(process_mapping_visible_instance_ids(),true);return array_values(array_filter(process_mapping_raw_rows('business_process_events','business_process_events','process_mapping_demo_events','created_at DESC,id DESC'),static fn(array$r):bool=>(!empty($r['instance_id'])&&isset($instances[(int)$r['instance_id']]))||(empty($r['instance_id'])&&!empty($r['process_id'])&&isset($processes[(int)$r['process_id']]))));}
function process_mapping_find(array$rows,int$id):?array{foreach($rows as$r)if((int)$r['id']===$id)return$r;return null;}
