function process_mapping_save_row(string$table,string$key,callable$seed,array$r,array$fields):array{process_mapping_require_tables();$r['created_at']=$r['created_at']??date('Y-m-d H:i:s');$r['updated_at']=date('Y-m-d H:i:s');if(data_is_demo())return process_mapping_demo_save($key,$r,$seed);$pdo=production_database_connection();$id=(int)($r['id']??0);$values=[];foreach($fields as$f){$v=$r[$f]??null;if(is_array($v))$v=json_encode($v,JSON_UNESCAPED_SLASHES);$values[]=$v;}if($id){$values[]=$id;$pdo->prepare('UPDATE '.$table.' SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).',updated_at=NOW() WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO '.$table.' ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($values);$id=(int)$pdo->lastInsertId();}$r['id']=$id;return$r;}
