function process_mapping_add_event(?int$processId,?int$versionId,?int$instanceId,?int$stepId,string$type,?string$from,?string$to,string$severity,string$note):array{process_mapping_require_tables();$r=['id'=>null,'process_id'=>$processId,'version_id'=>$versionId,'instance_id'=>$instanceId,'step_id'=>$stepId,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'severity'=>$severity,'evidence_note'=>$note,'created_by'=>(int)current_user()['id'],'created_at'=>date('Y-m-d H:i:s')];if(data_is_demo())return process_mapping_demo_save('business_process_events',$r,'process_mapping_demo_events');$p=production_database_connection();$p->prepare('INSERT INTO business_process_events(process_id,version_id,instance_id,step_id,event_type,from_status,to_status,severity,evidence_note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$processId,$versionId,$instanceId,$stepId,$type,$from,$to,$severity,$note,$r['created_by']]);$r['id']=(int)$p->lastInsertId();return$r;}
